<?php $pages=max(1,(int)ceil($count/$per));if($pages>1): ?><nav class="pagination" aria-label="صفحه‌بندی"><a href="<?= e(url($route,['p'=>1]+array_diff_key($filters,['page'=>true,'p'=>true]))) ?>">ابتدا</a><?php for($n=max(1,$page-2);$n<=min($pages,$page+2);$n++): ?><a href="<?= e(url($route,['p'=>$n]+array_diff_key($filters,['page'=>true,'p'=>true]))) ?>" <?= $page===$n?'aria-current="page"':'' ?>><?= fa($n) ?></a><?php endfor ?><a href="<?= e(url($route,['p'=>$pages]+array_diff_key($filters,['page'=>true,'p'=>true]))) ?>">آخر</a></nav><?php endif ?>
